-- 196: Original BrillaPrep WASSCE BrillaPrep transitional Basketry beta content blueprint questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_196_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_196_guard;
INSERT INTO _migration_196_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_013' AND NOT (q.topic_id IS 'topic_was_basketry_b004_3' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which procedure forms a simple overhand knot?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Wrap a working strand around a core and stitch each turn to the preceding one","B. Fold a cord into a bight and pull both ends through it around a support","C. Cross two separate cord ends twice in opposite directions to make a square knot","D. Make a loop in one cord, pass the working end through it once, and tighten"]' AND q.correct_answer IS 'D' AND q.explanation IS 'An overhand knot is the basic single-cord knot formed by passing the working end through its own loop; the other procedures create a square knot, lark’s head or wrapped coil. Therefore the correct answer is D: Make a loop in one cord, pass the working end through it once, and tighten.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_013' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_196_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_014' AND NOT (q.topic_id IS 'topic_was_basketry_b004_3' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What structure is produced by a square-knot sinnet in macrame?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A flat band of complete square knots repeated in sequence on the same cord group","B. A mounting row made by attaching folded cords to a support with lark''s-head knots","C. A ribbed line made by working double half hitches successively along a carrier cord","D. A spiral column made by repeating the same half-knot direction around filler cords"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A sinnet is a chain of repeated knots. Repeating complete square knots, each formed from opposing half-knots, produces a relatively flat band suitable for a basket handle or decorative structural strip. Therefore the correct answer is A: A flat band of complete square knots repeated in sequence on the same cord group.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_014' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_196_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_015' AND NOT (q.topic_id IS 'topic_was_basketry_b004_3' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which control is appropriate when mixing or applying a basketry dye?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Use suitable gloves, ventilation and the dye manufacturer’s handling guidance","B. Rely on an open window alone without checking the dye handling instructions","C. Decant leftover dye into an unlabelled drink bottle for later use","D. Increase concentration beyond guidance so gloves and ventilation are needed for less time"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Dyes and auxiliaries may irritate skin or release vapour, so labelled containers, ventilation, protective equipment and product-specific instructions reduce exposure and contamination risks. Therefore the correct answer is A: Use suitable gloves, ventilation and the dye manufacturer’s handling guidance.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_015' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_196_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_016' AND NOT (q.topic_id IS 'topic_was_basketry_b004_4' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In stake-and-strand basketry, what is the structural role of the stakes?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. They serve as temporary spacers and are removed when the sides are firm","B. They form the supporting framework around which the weavers pass","C. They are the flexible strands that complete the horizontal courses","D. They are decorative rim ends added only after the basket is complete"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Stakes establish the form and resist loads along the basket wall, while more flexible strands travel around them to bind the framework into a continuous surface. Therefore the correct answer is B: They form the supporting framework around which the weavers pass.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_016' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_013', 'topic_was_basketry_b004_3', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which procedure forms a simple overhand knot?', 'multiple_choice', NULL, '["A. Wrap a working strand around a core and stitch each turn to the preceding one","B. Fold a cord into a bight and pull both ends through it around a support","C. Cross two separate cord ends twice in opposite directions to make a square knot","D. Make a loop in one cord, pass the working end through it once, and tighten"]', 'D', 'An overhand knot is the basic single-cord knot formed by passing the working end through its own loop; the other procedures create a square knot, lark’s head or wrapped coil. Therefore the correct answer is D: Make a loop in one cord, pass the working end through it once, and tighten.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_3', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_014', 'topic_was_basketry_b004_3', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'What structure is produced by a square-knot sinnet in macrame?', 'multiple_choice', NULL, '["A. A flat band of complete square knots repeated in sequence on the same cord group","B. A mounting row made by attaching folded cords to a support with lark''s-head knots","C. A ribbed line made by working double half hitches successively along a carrier cord","D. A spiral column made by repeating the same half-knot direction around filler cords"]', 'A', 'A sinnet is a chain of repeated knots. Repeating complete square knots, each formed from opposing half-knots, produces a relatively flat band suitable for a basket handle or decorative structural strip. Therefore the correct answer is A: A flat band of complete square knots repeated in sequence on the same cord group.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_3', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_015', 'topic_was_basketry_b004_3', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which control is appropriate when mixing or applying a basketry dye?', 'multiple_choice', NULL, '["A. Use suitable gloves, ventilation and the dye manufacturer’s handling guidance","B. Rely on an open window alone without checking the dye handling instructions","C. Decant leftover dye into an unlabelled drink bottle for later use","D. Increase concentration beyond guidance so gloves and ventilation are needed for less time"]', 'A', 'Dyes and auxiliaries may irritate skin or release vapour, so labelled containers, ventilation, protective equipment and product-specific instructions reduce exposure and contamination risks. Therefore the correct answer is A: Use suitable gloves, ventilation and the dye manufacturer’s handling guidance.', 'hard', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_3', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_016', 'topic_was_basketry_b004_4', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'In stake-and-strand basketry, what is the structural role of the stakes?', 'multiple_choice', NULL, '["A. They serve as temporary spacers and are removed when the sides are firm","B. They form the supporting framework around which the weavers pass","C. They are the flexible strands that complete the horizontal courses","D. They are decorative rim ends added only after the basket is complete"]', 'B', 'Stakes establish the form and resist loads along the basket wall, while more flexible strands travel around them to bind the framework into a continuous surface. Therefore the correct answer is B: They form the supporting framework around which the weavers pass.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_4', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_basketry_b004_013', 'q_was_basketry_b004_014', 'q_was_basketry_b004_015', 'q_was_basketry_b004_016');
